old_factor = '''def factor(n):
    """Yield the prime factors of n.
    >>> list(factor(360))
    [2, 2, 2, 3, 3, 5]
    """
    for prime in sieve(math.isqrt(n) + 1):
        while True:
            if n % prime:
                break
            yield prime
            n //= prime
            if n == 1:
                return
    if n > 1:
        yield n'''

